package settingskey

import (
	"fmt"
	"strings"
)

// Documentation generates the committed settings reference from the registry.
func Documentation() string {
	out := ""
	out += "<!-- Generated by mise run docs:config; do not edit. -->\n\n# Machine settings\n\n"
	out += "Precedence: " + Precedence() + ". Empty flag/environment strings are unset. Only the winning override is validated; the stored file must always be valid.\n\n"
	out += "Use `kitbag config get <key>`, `set <key> <value>`, `unset <key>`, `list`, `explain <key>` or `edit`. Values for strings are raw text; booleans, integers and arrays use TOML literals. `get` prints the value, while `list` and `explain` include its source and redact sensitive values.\n\n"
	out += "`set` and `unset` validate the complete resulting file and write atomically with mode 0600. Required keys cannot be removed. Identity name/email must be changed together with `edit`. TOML encoding normalizes formatting; files containing any `#` are conservatively refused, including hashes inside strings. Use `edit` to preserve comments. Unknown keys are rejected. To create a file, first set `repo.url`, or use `init`/`edit`.\n\n"
	out += "`edit` runs `$EDITOR` as a shell command with a separate quoted draft filename argument. Editor arguments are supported. It validates on exit and offers re-edit or abort (the default, including EOF). The original stays intact on invalid input, editor failure or abort. A private adjacent draft is removed on exit; after a crash, inspect and remove the leftover draft before retrying. Configuration mutations share a nonblocking lock; external edits detected before saving are refused.\n\n"
	out += "`--config` > `KITBAG_CONFIG` > the platform config directory selects the file; these selectors are not config.toml keys. The repo, repo path, branch and identity flags apply to init only. Changing `repo.url` or `repo.path` with `set`/`unset` prints a note naming a former working copy that is no longer used; it is never deleted. Paths explicitly selected by config commands may be absent to allow first-run setup. Dynamic defaults: `host` uses the short hostname, `repo.branch` follows the remote default and `repo.path` uses the platform data directory. `sync.mode` defaults to link on Unix and copy on future Windows (Windows runtime is deferred).\n\n"
	out += "| Key | Type | Default | Environment | Flag | Allowed | Sensitive | Description |\n| --- | --- | --- | --- | --- | --- | --- | --- |\n"
	rows := make([]string, 0, len(Registry()))
	for _, key := range Registry() {
		fallback := key.DefaultDescription()
		if key.Path == "sync.mode" {
			fallback = "link (Unix), copy (Windows)"
		}
		rows = append(rows, fmt.Sprintf("| `%s` | %s | `%s` | `%s` | `%s` | %s | %t | %s |\n", key.Path, key.Type, fallback, key.Env, key.Flag, strings.ReplaceAll(key.Constraint(), "|", `\|`), key.Sensitive, key.Description))
	}
	return out + strings.Join(rows, "")
}
